      function addLog(message) {
        state.log.unshift(`[${nowTime()}] ${message}`);
        render();
      }

      function nextIndex() {
        return steps.findIndex((step) => !state.completed.has(step.id));
      }

      function canRun(index) {
        return index === nextIndex();
      }

      function complete(id, message) {
        state.completed.add(id);
        addLog(message);
      }

      function runStep(id) {
        const email = emailInput.value.trim().toLowerCase();
        if (!email || !email.includes("@")) {
          addLog("邮箱格式不正确，无法登录。");
          return;
