      function renderFlow() {
        const current = nextIndex();
        flow.innerHTML = steps
          .map((step, index) => {
            const done = state.completed.has(step.id);
            const active = index === current;
            const locked = index > current;
            const className = ["step", done ? "done" : "", active ? "active" : "", locked ? "locked" : ""]
              .filter(Boolean)
              .join(" ");
            const status = done ? "已完成" : active ? "当前步骤" : "等待前置步骤";
            return `
