import { createHash, randomBytes, randomInt } from "node:crypto";
import { createReadStream } from "node:fs";
import { readFile, stat } from "node:fs/promises";
import { createServer } from "node:http";
import { extname, join, normalize } from "node:path";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL(".", import.meta.url));
const port = Number(process.env.PORT || 8765);
const codes = new Map();
const sessions = new Map();

function json(res, status, payload, headers = {}) {
  res.writeHead(status, {
    "content-type": "application/json; charset=utf-8",
    "cache-control": "no-store",
    ...headers
  });
  res.end(JSON.stringify(payload));
}

function userIdForEmail(email) {
  return `user_${createHash("sha256").update(email).digest("hex").slice(0, 12)}`;
}

function parseCookies(header = "") {
  return Object.fromEntries(
    header
      .split(";")
      .map((item) => item.trim())
      .filter(Boolean)
      .map((item) => {
        const index = item.indexOf("=");
        return index === -1 ? [item, ""] : [item.slice(0, index), decodeURIComponent(item.slice(index + 1))];
      })
  );
}

async function readJson(req) {
  const chunks = [];
  for await (const chunk of req) chunks.push(chunk);
  const raw = Buffer.concat(chunks).toString("utf8");
  if (!raw) return {};
  return JSON.parse(raw);
}

function currentUser(req) {
  const sessionId = parseCookies(req.headers.cookie).ew_session;
  if (!sessionId) return null;
  const session = sessions.get(sessionId);
  if (!session || session.expiresAt < Date.now()) {
    sessions.delete(sessionId);
    return null;
  }
  return {
    email: session.email,
    userId: userIdForEmail(session.email)
  };
}

async function handleApi(req, res) {
  if (req.method === "POST" && req.url === "/api/auth/request-code") {
    const { email } = await readJson(req);
    const normalizedEmail = String(email || "").trim().toLowerCase();
    if (!normalizedEmail.includes("@")) {
      json(res, 400, { ok: false, error: "invalid_email" });
      return;
    }

    const code = String(randomInt(100000, 1000000));
    const expiresAt = Date.now() + 5 * 60 * 1000;
    codes.set(normalizedEmail, { code, expiresAt });
    console.log(`[email-wallet-demo] OTP for ${normalizedEmail}: ${code}`);
    json(res, 200, { ok: true, email: normalizedEmail, devCode: code, expiresInSeconds: 300 });
    return;
  }

  if (req.method === "POST" && req.url === "/api/auth/verify") {
    const { email, code } = await readJson(req);
    const normalizedEmail = String(email || "").trim().toLowerCase();
    const entry = codes.get(normalizedEmail);
    if (!entry || entry.expiresAt < Date.now()) {
      json(res, 400, { ok: false, error: "code_expired_or_missing" });
      return;
    }
    if (String(code || "").trim() !== entry.code) {
      json(res, 401, { ok: false, error: "invalid_code" });
      return;
    }

    codes.delete(normalizedEmail);
    const sessionId = randomBytes(24).toString("hex");
    sessions.set(sessionId, {
      email: normalizedEmail,
      expiresAt: Date.now() + 24 * 60 * 60 * 1000
    });

    json(
      res,
      200,
      { ok: true, email: normalizedEmail, userId: userIdForEmail(normalizedEmail) },
      { "set-cookie": `ew_session=${encodeURIComponent(sessionId)}; HttpOnly; SameSite=Lax; Path=/; Max-Age=86400` }
    );
    return;
  }

  if (req.method === "GET" && req.url === "/api/session") {
    const user = currentUser(req);
    json(res, 200, { ok: true, authenticated: Boolean(user), user });
    return;
  }

  if (req.method === "POST" && req.url === "/api/logout") {
    const sessionId = parseCookies(req.headers.cookie).ew_session;
    if (sessionId) sessions.delete(sessionId);
    json(res, 200, { ok: true }, { "set-cookie": "ew_session=; HttpOnly; SameSite=Lax; Path=/; Max-Age=0" });
    return;
  }

  json(res, 404, { ok: false, error: "not_found" });
}

async function serveStatic(req, res) {
  const url = new URL(req.url, `http://${req.headers.host}`);
  const requested = url.pathname === "/" ? "/email-wallet-demo.html" : decodeURIComponent(url.pathname);
  const safePath = normalize(requested).replace(/^(\.\.[/\\])+/, "");
  const filePath = join(root, safePath);
  if (!filePath.startsWith(root)) {
    res.writeHead(403);
    res.end("Forbidden");
    return;
  }

  try {
    const fileStat = await stat(filePath);
    if (!fileStat.isFile()) throw new Error("not_file");
    const contentType =
      extname(filePath) === ".html"
        ? "text/html; charset=utf-8"
        : extname(filePath) === ".js"
          ? "text/javascript; charset=utf-8"
          : "application/octet-stream";
    res.writeHead(200, { "content-type": contentType });
    createReadStream(filePath).pipe(res);
  } catch {
    const fallback = await readFile(join(root, "email-wallet-demo.html"), "utf8");
    res.writeHead(404, { "content-type": "text/html; charset=utf-8" });
    res.end(fallback);
  }
}

createServer(async (req, res) => {
  try {
    if (req.url?.startsWith("/api/")) {
      await handleApi(req, res);
      return;
    }
    await serveStatic(req, res);
  } catch (error) {
    console.error(error);
    json(res, 500, { ok: false, error: "server_error" });
  }
}).listen(port, "127.0.0.1", () => {
  console.log(`Email wallet local demo: http://127.0.0.1:${port}/email-wallet-demo.html`);
});

